import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadSikhData(){const e=readFileSync(resolve(__dirname,"../../sikh-empire-explorer/sikh-data.js"),"utf-8");return new Function(e+"\nreturn { SIKH_EMPIRE_INFO, TIMELINE_DATA, RULERS_DATA, CONTRIBUTIONS_DATA, GALLERY_IMAGES, REFERENCES };")()}describe("Sikh Empire Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadSikhData()}),describe("SIKH_EMPIRE_INFO metadata",()=>{it("contains correct Sikh Empire attributes",()=>{expect(e.SIKH_EMPIRE_INFO.id).toBe("sikh-empire"),expect(e.SIKH_EMPIRE_INFO.name).toContain("Sikh Empire"),expect(e.SIKH_EMPIRE_INFO.founder).toContain("Ranjit Singh"),expect(e.SIKH_EMPIRE_INFO.period).toContain("1799")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.SIKH_EMPIRE_INFO.quickStats)).toBe(!0),expect(e.SIKH_EMPIRE_INFO.quickStats.length).toBe(6)})}),describe("TIMELINE_DATA & RULERS_DATA",()=>{it("contains milestone timeline items and key rulers including Ranjit Singh & Hari Singh Nalwa",()=>{expect(Array.isArray(e.TIMELINE_DATA)).toBe(!0),expect(e.TIMELINE_DATA.length).toBeGreaterThanOrEqual(5),expect(Array.isArray(e.RULERS_DATA)).toBe(!0),expect(e.RULERS_DATA.length).toBeGreaterThanOrEqual(4)})}),describe("CONTRIBUTIONS_DATA",()=>{it("contains required contribution fields",()=>{expect(e.CONTRIBUTIONS_DATA.overview).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.faujIKhas).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.harmandirSahib).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.secularGovernance).toBeDefined(),expect(e.CONTRIBUTIONS_DATA.borderSecurity).toBeDefined()})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});